"""Camera-guided control record for putting_shoes_on_rack, eai-standard/2.2.
Commands and observations are retained under /app/runs and actions.jsonl.
No privileged state or reset is used.
"""
import sys, os, json, pickle, time, pathlib
import numpy as np
from PIL import Image,ImageDraw
from scipy.spatial.transform import Rotation as R
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot, EpisodeOver
ROOT=pathlib.Path('/app/output')
r=Robot()
s=r.spec()
CAMS=s['default_cameras']

def save(res):
    n=len(list(pathlib.Path('/app/runs').glob('[0-9]*')))
    folder=f'/app/runs/{n:04d}'
    res.save(folder)
    pickle.dump(res,open(ROOT/'obs.pkl','wb'))
    json.dump(res.meta,open(ROOT/'latest_meta.json','w'),indent=2)
    imgs=[]
    for c,arr in res.last.items():
        img=Image.fromarray(arr).resize((448,448))
        d=ImageDraw.Draw(img);d.text((6,6),c.split(':')[1],fill='red')
        imgs.append(img)
    if imgs:
        out=Image.new('RGB',(448*len(imgs),448))
        for i,img in enumerate(imgs):out.paste(img,(i*448,0))
        out.save(ROOT/'view.jpg')
    print('SAVED',folder,flush=True)
    print(json.dumps({k:v for k,v in res.meta.items() if k not in ['cameras','proprio']},default=str),flush=True)
    print('NOW',json.dumps(now(res)),flush=True)
    return res

def latest():return pickle.load(open(ROOT/'obs.pkl','rb'))
def now(o=None):
    o= o or latest()
    return dict(zip(o.meta['proprio']['layout'],o.meta['proprio']['now']))
def group(name,o=None):
    o=o or latest();return o.group(name,now=True)
def qnow(o=None):
    d=now(o);return np.array([d[j] for j in s['kinematics']['joint_names']])
def jnow(o=None):
    d=now(o)
    return np.array([0,0,0]+[d[j] for j in s['action_types']['joint_position']['layout'][3:]])
def record(typ,a,kw):
    with open(ROOT/'actions.jsonl','a') as f:f.write(json.dumps({'wall_time':time.time(),'type':typ,'actions':np.asarray(a).tolist(),'options':kw})+'\n')
def submit(typ,a,**kw):
    record(typ,a,kw)
    try:return save(r.submit(typ,a,depth=True,video='both',video_fps=5,**kw))
    except EpisodeOver as e:
        print('EPISODE OVER',e);print(r.status());raise
    except Exception as e:
        print('CALL ERROR',repr(e),flush=True)
        status=r.wait_ready();print('RESUMED STATUS',status,flush=True)
        save(r.get_obs(depth=True))
        raise

def obs():return save(r.get_obs(depth=True))
def joint(a,dt=.1):return submit('joint_position',a,dt=dt)
def move(dx=0,dy=0,dyaw=0,seconds=1):
    a=jnow();steps=round(seconds*30);a[:3]=np.array([dx,dy,dyaw])/steps
    return joint(np.tile(a,(steps,1)),dt=1/30)
def hold(seconds=1):return move(seconds=seconds)
def ee(left=None,right=None,lg=1,rg=1):
    d=now();poses=[]
    for arm,p,g in [('left',left,lg),('right',right,rg)]:
        if p is None:p=[d[f'{arm}_eef_{v}'] for v in ['x','y','z','qx','qy','qz','qw']]
        poses.extend(list(p)+[g])
    return submit('ee_pose',[poses])
def pixel(u,v,cam=0):
    o=latest();c=CAMS[cam] if isinstance(cam,int) else cam
    z=float(o.last_depth[c][int(v),int(u)])
    meta=o.meta['cameras'][c];K=np.array(meta['intrinsic_cv']);E=np.array(meta['extrinsic_cv'])
    p=np.linalg.inv(K)@np.array([u,v,1])*z
    pw=E[:,:3].T@(p-E[:,3])
    return pw

if __name__=='__main__':
    cmd=sys.argv[1] if len(sys.argv)>1 else 'obs'
    if cmd=='obs':obs()
    elif cmd=='status':print(r.status())
    elif cmd=='exec':exec(sys.argv[2])
PY
